SELECT * FROM customers LIMIT 10;

SELECT country, COUNT(*) AS num_customers FROM customers GROUP BY country;

SHOW CREATE TABLE customers;


CREATE DATABASE IF NOT EXISTS ClassicModels;

USE ClassicModels;

CREATE TABLE cust_country (
  customernumber int,
  customername string,
  contactlastname string,
  contactfirstname string,
  phone string,
  addressline1 string,
  addressline2 string,
  city string,
  state string,
  postalcode string,
  salesrepemployeenumber int,
  creditlimit double
)
PARTITIONED BY (country string)
STORED AS AVRO;

DESCRIBE FORMATTED cust_country;

SET hive.exec.dynamic.partition.mode=nonstrict;

INSERT INTO TABLE cust_country PARTITION (country)
SELECT customernumber, customername, contactlastname, contactfirstname, phone,
addressline1, addressline2, city, state, postalcode, salesrepemployeenumber, creditlimit, country
FROM customers
LIMIT 50;

SELECT * FROM cust_country LIMIT 10;

SHOW PARTITIONS cust_country;

SELECT * FROM cust_country WHERE country = 'USA';

EXPLAIN SELECT * FROM cust_country WHERE country = 'USA';

DESCRIBE FORMATTED cust_country;
